#ifndef TYPES_MOD
#define TYPES_MOD

// C++ type aliases corresponding to Fortran precision kind selectors.
// In Fortran, sp/dp/ex/qp are integer kind parameters used as real(dp), etc.
// Each alias maps to the closest standard C++ floating-point type.
namespace types {
  using sp = float;        // selected_real_kind(6)  -- single precision
  using dp = double;       // selected_real_kind(15) -- double precision
  using ex = long double;  // selected_real_kind(18) -- extended precision
  using qp = long double;  // selected_real_kind(33) -- quad precision (no standard C++ type)
}

#endif // TYPES_MOD
